import { useCallback, useEffect, useState } from 'react'
import { Navigate, NavLink, Route, Routes } from 'react-router-dom'
import type { Session } from '@supabase/supabase-js'
import {
  Activity, BriefcaseBusiness, Building2, CalendarDays, CheckCircle2, ChevronRight,
  ClipboardCheck, ContactRound, Gauge, HardHat, LogOut, Menu, Plus, ReceiptText,
  ShieldCheck, Truck, Users, Wifi, WifiOff, Wrench, X, UserRound, Clock3,
} from 'lucide-react'
import { supabase } from './lib/supabase'

type Organization = { id: string; name: string }
type Customer = { id: string; organization_id: string; name: string; billing_email: string | null; phone: string | null; address: string | null; notes: string | null; status: string }
type Employee = { id: string; organization_id: string; user_id?: string | null; first_name: string; last_name: string; email: string | null; phone: string | null; position: string | null; status: string }
type Vehicle = { id: string; organization_id: string; unit_number: string; name: string | null; vehicle_type: string; plate: string | null; status: string }
type Job = { id: string; organization_id: string; customer_id: string; job_number: string; title: string; site_name: string | null; site_address: string | null; scheduled_start: string | null; scheduled_end: string | null; status: string; notes: string | null }
type Assignment = { id: string; organization_id: string; job_id: string; employee_id: string | null; vehicle_id: string | null; role: string | null }
type AppData = { customers: Customer[]; employees: Employee[]; vehicles: Vehicle[]; jobs: Job[]; assignments: Assignment[] }
type DashboardView = 'manager' | 'operator' | 'client'

type Actions = {
  addCustomer: (input: Omit<Customer, 'id' | 'organization_id' | 'status'>) => Promise<Customer>
  updateCustomer: (id: string, input: Partial<Omit<Customer, 'id' | 'organization_id'>>) => Promise<void>
  addEmployee: (input: Omit<Employee, 'id' | 'organization_id' | 'status' | 'user_id'>) => Promise<void>
  updateEmployee: (id: string, input: Partial<Omit<Employee, 'id' | 'organization_id'>>) => Promise<void>
  addVehicle: (input: Omit<Vehicle, 'id' | 'organization_id' | 'status'>) => Promise<void>
  updateVehicle: (id: string, input: Partial<Omit<Vehicle, 'id' | 'organization_id'>>) => Promise<void>
  addJob: (input: Omit<Job, 'id' | 'organization_id' | 'status'>) => Promise<void>
  assignJob: (jobId: string, employeeIds: string[], vehicleIds: string[]) => Promise<void>
  removeAssignment: (assignment: Assignment) => Promise<void>
  updateJobStatus: (jobId: string, status: string) => Promise<void>
  resetTestData: () => void
}

const TEST_MODE_KEY = 'northborn_test_mode'
const TEST_DATA_KEY = 'northborn_test_data_v3'
const TEST_PASSWORD_HASH = '8c6976e5b5410415bde908bd4dee15dfb167a9c873fc4bb8a81f6f2ab448a918'
const TEST_ORGANIZATION: Organization = { id: '00000000-0000-0000-0000-000000000001', name: 'Northborn Test Company' }
const EMPTY_DATA: AppData = { customers: [], employees: [], vehicles: [], jobs: [], assignments: [] }
const modules = [
  ['Dashboard', '/', Gauge], ['Dispatch', '/dispatch', CalendarDays], ['Jobs', '/jobs', BriefcaseBusiness],
  ['Customers', '/customers', ContactRound], ['Employees', '/employees', Users], ['Fleet', '/fleet', Truck],
  ['Maintenance', '/maintenance', Wrench], ['Safety', '/safety', ShieldCheck], ['Tickets', '/tickets', ClipboardCheck],
  ['Timesheets', '/timesheets', HardHat], ['Invoices', '/invoices', ReceiptText], ['Reports', '/reports', Activity],
] as const
const makeId = () => crypto.randomUUID()

function createDemoData(): AppData {
  const now = new Date(); const start = new Date(now.getTime() + 60 * 60 * 1000); const end = new Date(start.getTime() + 8 * 60 * 60 * 1000)
  const organization_id = TEST_ORGANIZATION.id; const customerId = makeId(); const employeeOne = makeId(); const employeeTwo = makeId(); const vehicleOne = makeId(); const vehicleTwo = makeId(); const jobId = makeId()
  return {
    customers: [{ id: customerId, organization_id, name: 'Demo Energy Services', billing_email: 'billing@example.com', phone: '403-555-0100', address: 'Red Deer, AB', notes: 'Starter customer for testing.', status: 'active' }],
    employees: [
      { id: employeeOne, organization_id, user_id: 'test-admin', first_name: 'Garrett', last_name: 'Robson', email: 'garrett@example.com', phone: '403-555-0111', position: 'Operator', status: 'active' },
      { id: employeeTwo, organization_id, user_id: null, first_name: 'Test', last_name: 'Swamper', email: null, phone: null, position: 'Swamper', status: 'active' },
    ],
    vehicles: [
      { id: vehicleOne, organization_id, unit_number: '101', name: 'Hydrovac 101', vehicle_type: 'Hydrovac', plate: 'TEST101', status: 'assigned' },
      { id: vehicleTwo, organization_id, unit_number: '202', name: 'Combo Vac 202', vehicle_type: 'Combo Vac', plate: null, status: 'available' },
    ],
    jobs: [{ id: jobId, organization_id, customer_id: customerId, job_number: `JOB-${String(now.getFullYear()).slice(-2)}001`, title: 'Hydrovac daylighting demo job', site_name: 'North Site', site_address: 'Red Deer County, AB', scheduled_start: start.toISOString(), scheduled_end: end.toISOString(), status: 'dispatched', notes: 'Use this job to test Dispatch.' }],
    assignments: [
      { id: makeId(), organization_id, job_id: jobId, employee_id: employeeOne, vehicle_id: null, role: 'crew' },
      { id: makeId(), organization_id, job_id: jobId, employee_id: null, vehicle_id: vehicleOne, role: 'unit' },
    ],
  }
}
function readTestData(): AppData { try { const saved = localStorage.getItem(TEST_DATA_KEY); if (saved) return JSON.parse(saved) as AppData } catch {} const demo = createDemoData(); localStorage.setItem(TEST_DATA_KEY, JSON.stringify(demo)); return demo }
async function sha256(value: string) { const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value)); return Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, '0')).join('') }
function roleToView(role: string): DashboardView { if (['client', 'customer'].includes(role)) return 'client'; if (role === 'operator') return 'operator'; return 'manager' }

type AppProps = {
  resolvedSession?: Session | null
  authResolved?: boolean
}

export default function App({ resolvedSession, authResolved = false }: AppProps) {
  const [session, setSession] = useState<Session | null>(resolvedSession ?? null); const [testMode, setTestMode] = useState(() => localStorage.getItem(TEST_MODE_KEY) === '1')
  const [organization, setOrganization] = useState<Organization | null>(testMode ? TEST_ORGANIZATION : null); const [data, setData] = useState<AppData>(() => testMode ? readTestData() : EMPTY_DATA)
  const [loading, setLoading] = useState(!authResolved); const [dataLoading, setDataLoading] = useState(false); const [online, setOnline] = useState(navigator.onLine); const [mobileOpen, setMobileOpen] = useState(false)
  const [roleKey, setRoleKey] = useState(testMode ? 'owner' : ''); const [testView, setTestView] = useState<DashboardView>('manager')

  useEffect(() => {
    if (authResolved) {
      setSession(resolvedSession ?? null)
      setLoading(false)
      return
    }
    supabase.auth.getSession().then(({ data: d }) => { setSession(d.session); setLoading(false) })
    const { data: listener } = supabase.auth.onAuthStateChange((_event, next) => setSession(next))
    const onOnline = () => setOnline(true); const onOffline = () => setOnline(false); window.addEventListener('online', onOnline); window.addEventListener('offline', onOffline)
    return () => { listener.subscription.unsubscribe(); window.removeEventListener('online', onOnline); window.removeEventListener('offline', onOffline) }
  }, [authResolved, resolvedSession])

  useEffect(() => {
    if (testMode) { setOrganization(TEST_ORGANIZATION); setData(readTestData()); setRoleKey('owner'); return }
    if (!session) { setOrganization(null); setData(EMPTY_DATA); setRoleKey(''); return }
    supabase.from('organization_members').select('id,organization:organizations(id,name)').eq('user_id', session.user.id).eq('status', 'active').limit(1).maybeSingle().then(async ({ data: membership, error }) => {
      if (error) return console.error('Unable to load Northborn organization', error)
      const org = membership?.organization as unknown as Organization | null; setOrganization(org ?? null)
      if (membership?.id) {
        const { data: roleRows } = await supabase.from('membership_roles').select('role:roles(key,name)').eq('membership_id', membership.id)
        const role = ((roleRows?.[0]?.role as unknown as { key?: string } | null)?.key) || 'operator'; setRoleKey(role)
      }
    })
  }, [session, testMode])

  const refreshData = useCallback(async () => {
    if (testMode) { setData(readTestData()); return } if (!session || !organization) return
    setDataLoading(true)
    const [customers, employees, vehicles, jobs, assignments] = await Promise.all([
      supabase.from('customers').select('*').eq('organization_id', organization.id).order('name'),
      supabase.from('employees').select('*').eq('organization_id', organization.id).order('last_name'),
      supabase.from('fleet_vehicles').select('*').eq('organization_id', organization.id).order('unit_number'),
      supabase.from('jobs').select('*').eq('organization_id', organization.id).order('scheduled_start', { ascending: true }),
      supabase.from('dispatch_assignments').select('*').eq('organization_id', organization.id),
    ])
    const error = customers.error || employees.error || vehicles.error || jobs.error || assignments.error; if (error) console.error('Unable to load Northborn operations data', error)
    setData({ customers: (customers.data ?? []) as Customer[], employees: (employees.data ?? []) as Employee[], vehicles: (vehicles.data ?? []) as Vehicle[], jobs: (jobs.data ?? []) as Job[], assignments: (assignments.data ?? []) as Assignment[] }); setDataLoading(false)
  }, [testMode, session, organization])
  useEffect(() => { void refreshData() }, [refreshData])

  const saveTest = (next: AppData) => { localStorage.setItem(TEST_DATA_KEY, JSON.stringify(next)); setData(next) }
  const requireContext = () => { if (!organization) throw new Error('No organization is selected.'); if (!session && !testMode) throw new Error('You must be signed in.'); return { organizationId: organization.id, userId: session?.user.id ?? 'test-admin' } }

  const actions: Actions = {
    addCustomer: async (input) => { const { organizationId, userId } = requireContext(); const row = { ...input, id: makeId(), organization_id: organizationId, status: 'active' } as Customer; if (testMode) { saveTest({ ...data, customers: [...data.customers, row] }); return row } const result = await supabase.from('customers').insert({ ...input, organization_id: organizationId, created_by: userId }).select('*').single(); if (result.error) throw result.error; await refreshData(); return result.data as Customer },
    updateCustomer: async (id, input) => { const { organizationId } = requireContext(); if (testMode) { saveTest({ ...data, customers: data.customers.map(c => c.id === id ? { ...c, ...input } : c) }); return } const { error } = await supabase.from('customers').update(input).eq('id', id).eq('organization_id', organizationId); if (error) throw error; await refreshData() },
    addEmployee: async (input) => { const { organizationId, userId } = requireContext(); if (testMode) { saveTest({ ...data, employees: [...data.employees, { ...input, id: makeId(), organization_id: organizationId, user_id: null, status: 'active' }] }); return } const { error } = await supabase.from('employees').insert({ ...input, organization_id: organizationId, created_by: userId }); if (error) throw error; await refreshData() },
    updateEmployee: async (id, input) => { const { organizationId } = requireContext(); if (testMode) { saveTest({ ...data, employees: data.employees.map(e => e.id === id ? { ...e, ...input } : e) }); return } const { error } = await supabase.from('employees').update(input).eq('id', id).eq('organization_id', organizationId); if (error) throw error; await refreshData() },
    addVehicle: async (input) => { const { organizationId, userId } = requireContext(); if (testMode) { saveTest({ ...data, vehicles: [...data.vehicles, { ...input, id: makeId(), organization_id: organizationId, status: 'available' }] }); return } const { error } = await supabase.from('fleet_vehicles').insert({ ...input, organization_id: organizationId, created_by: userId }); if (error) throw error; await refreshData() },
    updateVehicle: async (id, input) => { const { organizationId } = requireContext(); if (testMode) { saveTest({ ...data, vehicles: data.vehicles.map(v => v.id === id ? { ...v, ...input } : v) }); return } const { error } = await supabase.from('fleet_vehicles').update(input).eq('id', id).eq('organization_id', organizationId); if (error) throw error; await refreshData() },
    addJob: async (input) => { const { organizationId, userId } = requireContext(); if (testMode) { saveTest({ ...data, jobs: [...data.jobs, { ...input, id: makeId(), organization_id: organizationId, status: 'scheduled' }] }); return } const { error } = await supabase.from('jobs').insert({ ...input, organization_id: organizationId, created_by: userId, status: 'scheduled' }); if (error) throw error; await refreshData() },
    assignJob: async (jobId, employeeIds, vehicleIds) => {
      const { organizationId, userId } = requireContext(); const existing = data.assignments.filter(a => a.job_id === jobId)
      const employeeRows = employeeIds.filter(id => !existing.some(a => a.employee_id === id)).map(id => ({ organization_id: organizationId, job_id: jobId, employee_id: id, vehicle_id: null, role: 'crew', created_by: userId }))
      const vehicleRows = vehicleIds.filter(id => !existing.some(a => a.vehicle_id === id)).map(id => ({ organization_id: organizationId, job_id: jobId, employee_id: null, vehicle_id: id, role: 'unit', created_by: userId }))
      const rows = [...employeeRows, ...vehicleRows]; if (!rows.length) throw new Error('Choose at least one new crew member or unit.')
      if (testMode) { const additions = rows.map(r => ({ ...r, id: makeId() })); saveTest({ ...data, assignments: [...data.assignments, ...additions], jobs: data.jobs.map(j => j.id === jobId ? { ...j, status: 'dispatched' } : j), vehicles: data.vehicles.map(v => vehicleIds.includes(v.id) ? { ...v, status: 'assigned' } : v) }); return }
      const { error } = await supabase.from('dispatch_assignments').insert(rows); if (error) throw error; await supabase.from('jobs').update({ status: 'dispatched' }).eq('id', jobId).eq('organization_id', organizationId); if (vehicleIds.length) await supabase.from('fleet_vehicles').update({ status: 'assigned' }).in('id', vehicleIds).eq('organization_id', organizationId); await refreshData()
    },
    removeAssignment: async (assignment) => { const { organizationId } = requireContext(); if (testMode) { saveTest({ ...data, assignments: data.assignments.filter(a => a.id !== assignment.id), vehicles: assignment.vehicle_id ? data.vehicles.map(v => v.id === assignment.vehicle_id ? { ...v, status: 'available' } : v) : data.vehicles }); return } const { error } = await supabase.from('dispatch_assignments').delete().eq('id', assignment.id).eq('organization_id', organizationId); if (error) throw error; if (assignment.vehicle_id) await supabase.from('fleet_vehicles').update({ status: 'available' }).eq('id', assignment.vehicle_id).eq('organization_id', organizationId); await refreshData() },
    updateJobStatus: async (jobId, status) => { const { organizationId } = requireContext(); const vehicleIds = data.assignments.filter(a => a.job_id === jobId).map(a => a.vehicle_id).filter(Boolean) as string[]; if (testMode) { saveTest({ ...data, jobs: data.jobs.map(j => j.id === jobId ? { ...j, status } : j), vehicles: status === 'completed' ? data.vehicles.map(v => vehicleIds.includes(v.id) ? { ...v, status: 'available' } : v) : data.vehicles }); return } const { error } = await supabase.from('jobs').update({ status }).eq('id', jobId).eq('organization_id', organizationId); if (error) throw error; if (status === 'completed' && vehicleIds.length) await supabase.from('fleet_vehicles').update({ status: 'available' }).in('id', vehicleIds).eq('organization_id', organizationId); await refreshData() },
    resetTestData: () => { const fresh = createDemoData(); localStorage.setItem(TEST_DATA_KEY, JSON.stringify(fresh)); setData(fresh) },
  }

  const signOut = async () => { if (testMode) { localStorage.removeItem(TEST_MODE_KEY); setTestMode(false); setOrganization(null); setData(EMPTY_DATA); return } await supabase.auth.signOut() }
  if (loading) return <div className="center-screen">Loading Northborn…</div>
  if (!session && !testMode) return <AuthScreen onTestLogin={() => { localStorage.setItem(TEST_MODE_KEY, '1'); setTestMode(true); setOrganization(TEST_ORGANIZATION); setData(readTestData()) }} />
  if (!organization) return <OrganizationSetup userId={session!.user.id} onCreated={setOrganization} />
  const dashboardView = testMode ? testView : roleToView(roleKey)

  return <div className="app-shell">
    <aside className={mobileOpen ? 'sidebar open' : 'sidebar'}><div className="brand"><div className="brand-mark">N</div><div><strong>NORTHBORN</strong><span>{organization.name}</span></div></div>{testMode && <div className="test-badge">TEST WORKSPACE</div>}<nav>{modules.map(([label, path, Icon]) => <NavLink key={path} to={path} end={path === '/'} onClick={() => setMobileOpen(false)}><Icon size={19}/><span>{label}</span></NavLink>)}</nav><button className="signout" onClick={signOut}><LogOut size={18}/>Sign out</button></aside>
    <main className="content"><header><button className="menu-button" aria-label="Open navigation" onClick={() => setMobileOpen(!mobileOpen)}><Menu/></button><div className="header-actions">{testMode && <div className="view-switcher"><span>Preview</span>{(['manager','operator','client'] as DashboardView[]).map(v => <button key={v} className={testView===v?'active':''} onClick={() => setTestView(v)}>{v}</button>)}</div>}{dataLoading && <span className="sync-text">Syncing…</span>}<div className={online ? 'connection online' : 'connection offline'}>{online ? <Wifi size={16}/> : <WifiOff size={16}/>} {online ? 'Online' : 'Offline'}</div></div></header>
      <Routes>
        <Route path="/" element={<Dashboard organization={organization} data={data} view={dashboardView} userId={session?.user.id ?? 'test-admin'} testMode={testMode} actions={actions} />} />
        <Route path="/customers" element={<CustomersPage data={data} actions={actions} />} /><Route path="/employees" element={<EmployeesPage data={data} actions={actions} />} /><Route path="/fleet" element={<FleetPage data={data} actions={actions} />} /><Route path="/jobs" element={<JobsPage data={data} actions={actions} />} /><Route path="/dispatch" element={<DispatchPage data={data} actions={actions} />} />
        {modules.slice(6).map(([label,path]) => <Route key={path} path={path} element={<ModulePage name={label}/>}/>)}<Route path="*" element={<Navigate to="/" replace/>}/>
      </Routes>
    </main>
  </div>
}

function AuthScreen({ onTestLogin }: { onTestLogin: () => void }) { const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [mode,setMode]=useState<'signin'|'signup'>('signin'); const [message,setMessage]=useState(''); const [submitting,setSubmitting]=useState(false); const submit=async(e:React.FormEvent)=>{e.preventDefault();setMessage('');setSubmitting(true);const normalized=email.trim().toLowerCase();if(mode==='signin'&&normalized==='admin'){const hash=await sha256(password);setSubmitting(false);if(hash===TEST_PASSWORD_HASH)return onTestLogin();return setMessage('Invalid login credentials')}const result=mode==='signin'?await supabase.auth.signInWithPassword({email:email.trim(),password}):await supabase.auth.signUp({email:email.trim(),password,options:{emailRedirectTo:window.location.origin}});setSubmitting(false);if(result.error)return setMessage(result.error.message);if(mode==='signup'&&!result.data.session)setMessage('Check your email to confirm your Northborn account.')}; return <div className="auth-page"><div className="auth-card"><div className="auth-logo">N</div><h1>Northborn</h1><p>Field operations, built for the work.</p><form onSubmit={submit}><label>Email or username<input value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength={mode==='signin'?1:8} required/></label>{message&&<div className="message">{message}</div>}<button className="primary" disabled={submitting}>{submitting?'Working…':mode==='signin'?'Sign in':'Create account'}</button></form>{mode==='signin'&&<div className="test-login-hint"><strong>Testing:</strong> admin / admin</div>}<button className="link-button" onClick={()=>{setMode(mode==='signin'?'signup':'signin');setMessage('')}}>{mode==='signin'?'New to Northborn? Create an account':'Already have an account? Sign in'}</button></div></div> }
function OrganizationSetup({userId,onCreated}:{userId:string;onCreated:(o:Organization)=>void}){const[name,setName]=useState('');const[error,setError]=useState('');const[submitting,setSubmitting]=useState(false);const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');setSubmitting(true);const result=await supabase.from('organizations').insert({name:name.trim(),created_by:userId}).select('id,name').single();setSubmitting(false);if(result.error)return setError(result.error.message);onCreated(result.data)};return <div className="auth-page"><div className="auth-card"><Building2 size={42}/><h1>Create your company</h1><p>This becomes your private Northborn workspace.</p><form onSubmit={submit}><label>Company name<input value={name} onChange={e=>setName(e.target.value)} required minLength={2}/></label>{error&&<div className="message">{error}</div>}<button className="primary" disabled={submitting}>{submitting?'Creating…':'Create company'}</button></form></div></div>}

function Dashboard({ organization, data, view, userId, testMode, actions }: { organization: Organization; data: AppData; view: DashboardView; userId: string; testMode: boolean; actions: Actions }) {
  if (view === 'operator') return <OperatorDashboard data={data} userId={userId} testMode={testMode}/>
  if (view === 'client') return <ClientDashboard data={data}/>
  const activeJobs=data.jobs.filter(j=>!['completed','cancelled'].includes(j.status));const available=data.vehicles.filter(v=>v.status==='available');const activeStaff=data.employees.filter(e=>e.status==='active');const unassigned=activeJobs.filter(j=>!data.assignments.some(a=>a.job_id===j.id));const upcoming=[...activeJobs].sort((a,b)=>String(a.scheduled_start).localeCompare(String(b.scheduled_start))).slice(0,5)
  return <section className="page"><div className="dashboard-hero"><div><div className="eyebrow">COMPANY OVERVIEW</div><h1>{organization.name}</h1><p>What needs attention, what is moving, and what is coming next.</p></div><div className="hero-actions"><NavLink className="primary compact" to="/jobs"><Plus size={17}/>New job</NavLink><NavLink className="secondary" to="/dispatch">Open dispatch</NavLink></div></div>
    {testMode&&<div className="notice"><div><strong>Test workspace is active.</strong><span>Use the preview switch above to test manager, operator and client dashboards.</span></div><button className="secondary" onClick={actions.resetTestData}>Reset demo data</button></div>}
    <div className="metric-grid"><MetricLink to="/jobs" icon={<BriefcaseBusiness/>} title="Active jobs" value={String(activeJobs.length)} detail={`${data.jobs.filter(j=>j.status==='dispatched').length} dispatched`}/><MetricLink to="/fleet" icon={<Truck/>} title="Available units" value={String(available.length)} detail={`${data.vehicles.length} total units`}/><MetricLink to="/employees" icon={<Users/>} title="Active staff" value={String(activeStaff.length)} detail={`${data.employees.length} employee records`}/><MetricLink to="/dispatch" icon={<CalendarDays/>} title="Needs dispatch" value={String(unassigned.length)} detail="Jobs without crew or unit"/></div>
    <div className="dashboard-columns"><div className="panel"><SectionTitle eyebrow="NEXT UP" title="Upcoming work" link="/jobs"/><div className="list-stack">{upcoming.length?upcoming.map(j=><JobRow key={j.id} job={j} data={data} to="/dispatch"/>):<EmptyState title="No jobs scheduled" copy="Create a job to start building the board."/>}</div></div><div className="panel"><SectionTitle eyebrow="QUICK ACCESS" title="Run the day"/><div className="quick-grid"><QuickLink to="/dispatch" icon={<CalendarDays/>} title="Dispatch" copy="Build crews and assign units"/><QuickLink to="/jobs" icon={<BriefcaseBusiness/>} title="Jobs" copy="Create and schedule work"/><QuickLink to="/fleet" icon={<Truck/>} title="Fleet" copy="Check unit availability"/><QuickLink to="/employees" icon={<Users/>} title="Employees" copy="Open staff records"/></div></div></div>
  </section>
}
function OperatorDashboard({data,userId,testMode}:{data:AppData;userId:string;testMode:boolean}){const employee=data.employees.find(e=>e.user_id===userId)||(testMode?data.employees[0]:undefined);const assignmentIds=new Set(data.assignments.filter(a=>a.employee_id===employee?.id).map(a=>a.job_id));const jobs=data.jobs.filter(j=>assignmentIds.has(j.id)&&!['completed','cancelled'].includes(j.status));const next=jobs[0];return <section className="page"><PageHeading eyebrow="MY WORK" title={employee?`Hi, ${employee.first_name}`:'Operator dashboard'} subtitle="Your assigned work without the office clutter."/>{!employee&&<EmptyPanel title="No employee profile linked" copy="An administrator needs to link this login to an employee record."/>}{employee&&<><div className="operator-focus">{next?<><div><span className="eyebrow">NEXT ASSIGNMENT</span><h2>{next.title}</h2><p>{next.site_name||next.site_address||'Site not set'}</p><div className="focus-time"><Clock3 size={17}/>{formatDate(next.scheduled_start)}</div></div><NavLink className="primary" to="/dispatch">Open assignment <ChevronRight size={17}/></NavLink></>:<EmptyState title="No active assignments" copy="Nothing is currently assigned to you."/>}</div><div className="metric-grid operator-metrics"><MetricLink to="/dispatch" icon={<BriefcaseBusiness/>} title="My active jobs" value={String(jobs.length)} detail="Assigned to you"/><MetricLink to="/tickets" icon={<ClipboardCheck/>} title="Tickets" value="Open" detail="Field tickets and paperwork"/><MetricLink to="/timesheets" icon={<HardHat/>} title="Timesheet" value="Today" detail="Hours and shift entry"/><MetricLink to="/safety" icon={<ShieldCheck/>} title="Safety" value="Ready" detail="Forms and compliance"/></div></>}</section>}
function ClientDashboard({data}:{data:AppData}){const customer=data.customers[0];const jobs=customer?data.jobs.filter(j=>j.customer_id===customer.id):[];return <section className="page"><PageHeading eyebrow="CLIENT PORTAL" title={customer?.name||'Client dashboard'} subtitle="A clean view of your work, tickets and billing."/><div className="client-banner"><div><span className="eyebrow">ACCOUNT OVERVIEW</span><h2>{jobs.filter(j=>!['completed','cancelled'].includes(j.status)).length} active jobs</h2><p>Your company view will only show records belonging to your customer account.</p></div><ShieldCheck size={34}/></div><div className="metric-grid"><MetricLink to="/jobs" icon={<BriefcaseBusiness/>} title="Active work" value={String(jobs.filter(j=>!['completed','cancelled'].includes(j.status)).length)} detail="Scheduled or in progress"/><MetricLink to="/tickets" icon={<ClipboardCheck/>} title="Tickets" value="View" detail="Completed field documents"/><MetricLink to="/invoices" icon={<ReceiptText/>} title="Invoices" value="View" detail="Outstanding and paid"/><MetricLink to="/reports" icon={<Activity/>} title="YTD activity" value={String(jobs.length)} detail="Jobs this account"/></div><div className="panel"><SectionTitle eyebrow="YOUR WORK" title="Recent jobs"/>{jobs.length?<div className="list-stack">{jobs.slice(0,6).map(j=><JobRow key={j.id} job={j} data={data}/>)}</div>:<EmptyState title="No jobs yet" copy="Jobs for this customer will appear here."/>}</div></section>}

function CustomersPage({data,actions}:{data:AppData;actions:Actions}){const[open,setOpen]=useState(false);const[selected,setSelected]=useState<Customer|null>(null);const[error,setError]=useState('');const[form,setForm]=useState({name:'',billing_email:'',phone:'',address:'',notes:''});const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');try{await actions.addCustomer({...form,billing_email:form.billing_email||null,phone:form.phone||null,address:form.address||null,notes:form.notes||null});setForm({name:'',billing_email:'',phone:'',address:'',notes:''});setOpen(false)}catch(err){setError(readError(err))}};return <section className="page"><PageHeading eyebrow="CRM" title="Customers" subtitle="Companies you work for and bill." action={<button className="primary compact" onClick={()=>setOpen(true)}><Plus size={17}/>Add customer</button>}/>{open&&<InlineForm title="New customer" error={error} onSubmit={submit}><CustomerFields form={form} setForm={setForm}/><FormActions onCancel={()=>setOpen(false)}/></InlineForm>}<div className="card-grid">{data.customers.map(c=><button className="record-card clickable" key={c.id} onClick={()=>setSelected(c)}><div className="record-icon"><Building2 size={20}/></div><div><h3>{c.name}</h3><p>{c.address||'No address yet'}</p><div className="record-meta"><span>{c.billing_email||'No billing email'}</span><span>{c.phone||'No phone'}</span></div></div><ChevronRight className="record-chevron" size={18}/></button>)}</div>{!data.customers.length&&<EmptyPanel title="No customers yet" copy="Add the first company you want to dispatch work for."/>}{selected&&<CustomerModal customer={selected} actions={actions} onClose={()=>setSelected(null)}/>}</section>}
function CustomerFields({form,setForm}:{form:{name:string;billing_email:string;phone:string;address:string;notes:string};setForm:React.Dispatch<React.SetStateAction<{name:string;billing_email:string;phone:string;address:string;notes:string}>>}){return <><FormGrid><Field label="Company name"><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required/></Field><Field label="Billing email"><input type="email" value={form.billing_email} onChange={e=>setForm({...form,billing_email:e.target.value})}/></Field><Field label="Phone"><input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></Field><Field label="Address"><input value={form.address} onChange={e=>setForm({...form,address:e.target.value})}/></Field></FormGrid><Field label="Notes"><textarea value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></Field></>}
function CustomerModal({customer,actions,onClose}:{customer:Customer;actions:Actions;onClose:()=>void}){const[form,setForm]=useState({name:customer.name,billing_email:customer.billing_email||'',phone:customer.phone||'',address:customer.address||'',notes:customer.notes||''});const[error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await actions.updateCustomer(customer.id,{name:form.name,billing_email:form.billing_email||null,phone:form.phone||null,address:form.address||null,notes:form.notes||null});onClose()}catch(err){setError(readError(err))}};return <Modal title="Customer details" onClose={onClose}><form onSubmit={submit}><CustomerFields form={form} setForm={setForm}/>{error&&<div className="message">{error}</div>}<FormActions onCancel={onClose}/></form></Modal>}

function EmployeesPage({data,actions}:{data:AppData;actions:Actions}){const[open,setOpen]=useState(false);const[selected,setSelected]=useState<Employee|null>(null);const[error,setError]=useState('');const[form,setForm]=useState({first_name:'',last_name:'',email:'',phone:'',position:'Operator'});const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await actions.addEmployee({...form,email:form.email||null,phone:form.phone||null,position:form.position||null});setForm({first_name:'',last_name:'',email:'',phone:'',position:'Operator'});setOpen(false)}catch(err){setError(readError(err))}};return <section className="page"><PageHeading eyebrow="WORKFORCE" title="Employees" subtitle="Tap any employee to view or edit their record." action={<button className="primary compact" onClick={()=>setOpen(true)}><Plus size={17}/>Add employee</button>}/>{open&&<InlineForm title="New employee" error={error} onSubmit={submit}><EmployeeFields form={form} setForm={setForm}/><FormActions onCancel={()=>setOpen(false)}/></InlineForm>}<div className="card-grid">{data.employees.map(e=><button className="record-card clickable" key={e.id} onClick={()=>setSelected(e)}><div className="record-icon"><HardHat size={20}/></div><div><h3>{e.first_name} {e.last_name}</h3><p>{e.position||'No position set'}</p><div className="record-meta"><span>{e.email||e.phone||'No contact info'}</span><StatusPill status={e.status}/></div></div><ChevronRight className="record-chevron" size={18}/></button>)}</div>{selected&&<EmployeeModal employee={selected} actions={actions} onClose={()=>setSelected(null)}/>}</section>}
function EmployeeFields({form,setForm}:{form:{first_name:string;last_name:string;email:string;phone:string;position:string};setForm:React.Dispatch<React.SetStateAction<{first_name:string;last_name:string;email:string;phone:string;position:string}>>}){return <FormGrid><Field label="First name"><input value={form.first_name} onChange={e=>setForm({...form,first_name:e.target.value})} required/></Field><Field label="Last name"><input value={form.last_name} onChange={e=>setForm({...form,last_name:e.target.value})} required/></Field><Field label="Position"><input value={form.position} onChange={e=>setForm({...form,position:e.target.value})}/></Field><Field label="Email"><input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></Field><Field label="Phone"><input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></Field></FormGrid>}
function EmployeeModal({employee,actions,onClose}:{employee:Employee;actions:Actions;onClose:()=>void}){const[form,setForm]=useState({first_name:employee.first_name,last_name:employee.last_name,email:employee.email||'',phone:employee.phone||'',position:employee.position||''});const[status,setStatus]=useState(employee.status);const[error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await actions.updateEmployee(employee.id,{...form,email:form.email||null,phone:form.phone||null,position:form.position||null,status});onClose()}catch(err){setError(readError(err))}};return <Modal title={`${employee.first_name} ${employee.last_name}`} subtitle="Employee profile" onClose={onClose}><form onSubmit={submit}><EmployeeFields form={form} setForm={setForm}/><Field label="Status"><select value={status} onChange={e=>setStatus(e.target.value)}><option value="active">Active</option><option value="leave">Leave</option><option value="inactive">Inactive</option><option value="archived">Archived</option></select></Field>{error&&<div className="message">{error}</div>}<FormActions onCancel={onClose}/></form></Modal>}

function FleetPage({data,actions}:{data:AppData;actions:Actions}){const[open,setOpen]=useState(false);const[selected,setSelected]=useState<Vehicle|null>(null);const[error,setError]=useState('');const[form,setForm]=useState({unit_number:'',name:'',vehicle_type:'Hydrovac',plate:''});const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await actions.addVehicle({...form,name:form.name||null,plate:form.plate||null});setForm({unit_number:'',name:'',vehicle_type:'Hydrovac',plate:''});setOpen(false)}catch(err){setError(readError(err))}};return <section className="page"><PageHeading eyebrow="FLEET" title="Fleet" subtitle="Tap a unit to open its details and edit it." action={<button className="primary compact" onClick={()=>setOpen(true)}><Plus size={17}/>Add unit</button>}/>{open&&<InlineForm title="New fleet unit" error={error} onSubmit={submit}><VehicleFields form={form} setForm={setForm}/><FormActions onCancel={()=>setOpen(false)}/></InlineForm>}<div className="card-grid">{data.vehicles.map(v=><button className="record-card clickable" key={v.id} onClick={()=>setSelected(v)}><div className="record-icon"><Truck size={20}/></div><div><h3>Unit {v.unit_number}</h3><p>{v.name||v.vehicle_type}</p><div className="record-meta"><span>{v.vehicle_type}</span><StatusPill status={v.status}/></div></div><ChevronRight className="record-chevron" size={18}/></button>)}</div>{selected&&<VehicleModal vehicle={selected} actions={actions} onClose={()=>setSelected(null)}/>}</section>}
function VehicleFields({form,setForm}:{form:{unit_number:string;name:string;vehicle_type:string;plate:string};setForm:React.Dispatch<React.SetStateAction<{unit_number:string;name:string;vehicle_type:string;plate:string}>>}){return <FormGrid><Field label="Unit number"><input value={form.unit_number} onChange={e=>setForm({...form,unit_number:e.target.value})} required/></Field><Field label="Unit name"><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Hydrovac 101"/></Field><Field label="Type"><select value={form.vehicle_type} onChange={e=>setForm({...form,vehicle_type:e.target.value})}><option>Hydrovac</option><option>Combo Vac</option><option>Straight Vac</option><option>Water Truck</option><option>Steamer</option><option>Pickup</option><option>Other</option></select></Field><Field label="Plate"><input value={form.plate} onChange={e=>setForm({...form,plate:e.target.value})}/></Field></FormGrid>}
function VehicleModal({vehicle,actions,onClose}:{vehicle:Vehicle;actions:Actions;onClose:()=>void}){const[form,setForm]=useState({unit_number:vehicle.unit_number,name:vehicle.name||'',vehicle_type:vehicle.vehicle_type,plate:vehicle.plate||''});const[status,setStatus]=useState(vehicle.status);const[error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();try{await actions.updateVehicle(vehicle.id,{...form,name:form.name||null,plate:form.plate||null,status});onClose()}catch(err){setError(readError(err))}};return <Modal title={`Unit ${vehicle.unit_number}`} subtitle={vehicle.name||vehicle.vehicle_type} onClose={onClose}><form onSubmit={submit}><VehicleFields form={form} setForm={setForm}/><Field label="Status"><select value={status} onChange={e=>setStatus(e.target.value)}><option value="available">Available</option><option value="assigned">Assigned</option><option value="maintenance">Maintenance</option><option value="out_of_service">Out of service</option><option value="archived">Archived</option></select></Field>{error&&<div className="message">{error}</div>}<FormActions onCancel={onClose}/></form></Modal>}

function JobsPage({data,actions}:{data:AppData;actions:Actions}){const[open,setOpen]=useState(false);const[clientOpen,setClientOpen]=useState(false);const[error,setError]=useState('');const[clientError,setClientError]=useState('');const[clientForm,setClientForm]=useState({name:'',billing_email:'',phone:'',address:'',notes:''});const[form,setForm]=useState({customer_id:data.customers[0]?.id??'',job_number:'',title:'',site_name:'',site_address:'',scheduled_start:'',scheduled_end:'',notes:''});useEffect(()=>{if(!form.customer_id&&data.customers[0])setForm(c=>({...c,customer_id:data.customers[0].id}))},[data.customers,form.customer_id]);const submit=async(e:React.FormEvent)=>{e.preventDefault();try{const jobNumber=form.job_number||`JOB-${new Date().toISOString().replace(/\D/g,'').slice(2,12)}`;await actions.addJob({customer_id:form.customer_id,job_number:jobNumber,title:form.title,site_name:form.site_name||null,site_address:form.site_address||null,scheduled_start:form.scheduled_start?new Date(form.scheduled_start).toISOString():null,scheduled_end:form.scheduled_end?new Date(form.scheduled_end).toISOString():null,notes:form.notes||null});setForm({customer_id:data.customers[0]?.id??'',job_number:'',title:'',site_name:'',site_address:'',scheduled_start:'',scheduled_end:'',notes:''});setOpen(false)}catch(err){setError(readError(err))}};const addClient=async(e:React.FormEvent)=>{e.preventDefault();try{const c=await actions.addCustomer({...clientForm,billing_email:clientForm.billing_email||null,phone:clientForm.phone||null,address:clientForm.address||null,notes:clientForm.notes||null});setForm(f=>({...f,customer_id:c.id}));setClientForm({name:'',billing_email:'',phone:'',address:'',notes:''});setClientOpen(false);setOpen(true)}catch(err){setClientError(readError(err))}};return <section className="page"><PageHeading eyebrow="OPERATIONS" title="Jobs" subtitle="Create work, schedule it and send it to Dispatch." action={<div className="heading-actions"><button className="secondary" onClick={()=>setClientOpen(true)}><Plus size={17}/>New client</button><button className="primary compact" disabled={!data.customers.length} onClick={()=>setOpen(true)}><Plus size={17}/>New job</button></div>}/>{!data.customers.length&&<div className="notice"><div><strong>No clients yet.</strong><span>Add one here without leaving Jobs.</span></div><button className="secondary" onClick={()=>setClientOpen(true)}>Add client</button></div>}{open&&<InlineForm title="New job" error={error} onSubmit={submit}><FormGrid><Field label="Customer"><div className="inline-control"><select value={form.customer_id} onChange={e=>setForm({...form,customer_id:e.target.value})} required>{data.customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><button type="button" className="mini-add" onClick={()=>setClientOpen(true)}><Plus size={16}/></button></div></Field><Field label="Job number"><input value={form.job_number} onChange={e=>setForm({...form,job_number:e.target.value})} placeholder="Auto if blank"/></Field><Field label="Job title"><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} required/></Field><Field label="Site name"><input value={form.site_name} onChange={e=>setForm({...form,site_name:e.target.value})}/></Field><Field label="Site address"><input value={form.site_address} onChange={e=>setForm({...form,site_address:e.target.value})}/></Field><Field label="Start"><input type="datetime-local" value={form.scheduled_start} onChange={e=>setForm({...form,scheduled_start:e.target.value})}/></Field><Field label="End"><input type="datetime-local" value={form.scheduled_end} onChange={e=>setForm({...form,scheduled_end:e.target.value})}/></Field></FormGrid><Field label="Notes"><textarea value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></Field><FormActions onCancel={()=>setOpen(false)}/></InlineForm>}<div className="list-stack">{data.jobs.map(j=><JobRow key={j.id} job={j} data={data} to="/dispatch"/>)}</div>{!data.jobs.length&&<EmptyPanel title="No jobs yet" copy="Create a job and it will appear here and in Dispatch."/>}{clientOpen&&<Modal title="Add client" subtitle="Create a customer without leaving the job workflow." onClose={()=>setClientOpen(false)}><form onSubmit={addClient}><CustomerFields form={clientForm} setForm={setClientForm}/>{clientError&&<div className="message">{clientError}</div>}<FormActions onCancel={()=>setClientOpen(false)}/></form></Modal>}</section>}

function DispatchPage({data,actions}:{data:AppData;actions:Actions}){const jobs=data.jobs.filter(j=>!['completed','cancelled'].includes(j.status));const assigned=jobs.filter(j=>data.assignments.some(a=>a.job_id===j.id)).length;return <section className="page"><div className="dispatch-heading"><PageHeading eyebrow="LIVE BOARD" title="Dispatch" subtitle="Build the whole crew, assign units and move the day forward."/><div className="dispatch-summary"><span><strong>{jobs.length}</strong> active jobs</span><span><strong>{assigned}</strong> assigned</span></div></div><div className="dispatch-board">{jobs.map(j=><DispatchCard key={j.id} job={j} data={data} actions={actions}/>)}</div>{!jobs.length&&<EmptyPanel title="Nothing on the board" copy="Create a scheduled job and it will appear here."/>}</section>}
function DispatchCard({job,data,actions}:{job:Job;data:AppData;actions:Actions}){const[selectedEmployees,setSelectedEmployees]=useState<string[]>([]);const[selectedVehicles,setSelectedVehicles]=useState<string[]>([]);const[error,setError]=useState('');const assignments=data.assignments.filter(a=>a.job_id===job.id);const customer=data.customers.find(c=>c.id===job.customer_id);const crewAssignments=assignments.filter(a=>a.employee_id);const unitAssignments=assignments.filter(a=>a.vehicle_id);const toggle=(list:string[],setList:(v:string[])=>void,id:string)=>setList(list.includes(id)?list.filter(x=>x!==id):[...list,id]);const assign=async()=>{setError('');try{await actions.assignJob(job.id,selectedEmployees,selectedVehicles);setSelectedEmployees([]);setSelectedVehicles([])}catch(err){setError(readError(err))}};return <article className="dispatch-card"><div className="dispatch-top"><div><span className="job-number">{job.job_number}</span><h2>{job.title}</h2><p>{customer?.name||'Unknown customer'} · {job.site_name||job.site_address||'Site not set'}</p></div><StatusPill status={job.status}/></div><div className="dispatch-time"><CalendarDays size={16}/>{formatDate(job.scheduled_start)}</div><div className="assigned-section"><div className="assigned-label">Crew</div><div className="assignment-chips">{crewAssignments.length?crewAssignments.map(a=>{const e=data.employees.find(x=>x.id===a.employee_id);return e?<span className="assignment-chip" key={a.id}>{e.first_name} {e.last_name}<button onClick={()=>actions.removeAssignment(a)} aria-label="Remove crew member"><X size={13}/></button></span>:null}):<span className="muted">No crew assigned</span>}</div></div><div className="assigned-section"><div className="assigned-label">Units</div><div className="assignment-chips">{unitAssignments.length?unitAssignments.map(a=>{const v=data.vehicles.find(x=>x.id===a.vehicle_id);return v?<span className="assignment-chip" key={a.id}>#{v.unit_number} {v.name||v.vehicle_type}<button onClick={()=>actions.removeAssignment(a)} aria-label="Remove unit"><X size={13}/></button></span>:null}):<span className="muted">No units assigned</span>}</div></div><div className="dispatch-picker"><div><div className="picker-title">Add crew</div><div className="selection-grid">{data.employees.filter(e=>e.status==='active').map(e=>{const already=crewAssignments.some(a=>a.employee_id===e.id);const active=selectedEmployees.includes(e.id);return <button type="button" disabled={already} className={active?'select-chip active':'select-chip'} key={e.id} onClick={()=>toggle(selectedEmployees,setSelectedEmployees,e.id)}><UserRound size={15}/>{e.first_name} {e.last_name}{already&&<small>Assigned</small>}</button>})}</div></div><div><div className="picker-title">Add units</div><div className="selection-grid">{data.vehicles.filter(v=>v.status==='available'||unitAssignments.some(a=>a.vehicle_id===v.id)).map(v=>{const already=unitAssignments.some(a=>a.vehicle_id===v.id);const active=selectedVehicles.includes(v.id);return <button type="button" disabled={already} className={active?'select-chip active':'select-chip'} key={v.id} onClick={()=>toggle(selectedVehicles,setSelectedVehicles,v.id)}><Truck size={15}/>#{v.unit_number} {v.name||v.vehicle_type}{already&&<small>Assigned</small>}</button>})}</div></div></div><div className="dispatch-footer">{error&&<div className="message">{error}</div>}<div className="dispatch-buttons"><button className="secondary" disabled={!selectedEmployees.length&&!selectedVehicles.length} onClick={assign}>Assign selected ({selectedEmployees.length+selectedVehicles.length})</button>{job.status!=='in_progress'&&<button onClick={()=>actions.updateJobStatus(job.id,'in_progress')}>Start job</button>}<button className="complete" onClick={()=>actions.updateJobStatus(job.id,'completed')}><CheckCircle2 size={16}/>Complete</button></div></div></article>}

function Modal({title,subtitle,onClose,children}:{title:string;subtitle?:string;onClose:()=>void;children:React.ReactNode}){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal-card" role="dialog" aria-modal="true"><div className="modal-head"><div><span className="eyebrow">DETAILS</span><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-button" onClick={onClose}><X/></button></div>{children}</div></div>}
function PageHeading({eyebrow,title,subtitle,action}:{eyebrow:string;title:string;subtitle:string;action?:React.ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p className="subtitle">{subtitle}</p></div>{action}</div>}
function InlineForm({title,error,onSubmit,children}:{title:string;error:string;onSubmit:(e:React.FormEvent)=>void;children:React.ReactNode}){return <form className="panel form-panel" onSubmit={onSubmit}><h2>{title}</h2>{children}{error&&<div className="message">{error}</div>}</form>}
function FormGrid({children}:{children:React.ReactNode}){return <div className="form-grid">{children}</div>} function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>} function FormActions({onCancel}:{onCancel:()=>void}){return <div className="form-actions"><button type="button" className="secondary" onClick={onCancel}>Cancel</button><button className="primary" type="submit">Save</button></div>}
function MetricLink({to,icon,title,value,detail}:{to:string;icon:React.ReactNode;title:string;value:string;detail:string}){return <NavLink to={to} className="metric metric-link"><div className="metric-icon">{icon}</div><span>{title}</span><strong>{value}</strong><small>{detail}</small><ChevronRight className="metric-arrow" size={18}/></NavLink>}
function QuickLink({to,icon,title,copy}:{to:string;icon:React.ReactNode;title:string;copy:string}){return <NavLink to={to} className="quick-link"><div className="record-icon">{icon}</div><div><strong>{title}</strong><span>{copy}</span></div><ChevronRight size={17}/></NavLink>}
function SectionTitle({eyebrow,title,link}:{eyebrow:string;title:string;link?:string}){return <div className="section-title"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div>{link&&<NavLink className="text-link" to={link}>View all</NavLink>}</div>}
function StatusPill({status}:{status:string}){return <span className={`status-pill status-${status}`}>{status.replaceAll('_',' ')}</span>}
function JobRow({job,data,to}:{job:Job;data:AppData;to?:string}){const customer=data.customers.find(c=>c.id===job.customer_id);const content=<><div className="job-row-main"><span className="job-number">{job.job_number}</span><strong>{job.title}</strong><span>{customer?.name||'Unknown customer'}</span></div><div className="job-row-meta"><span>{formatDate(job.scheduled_start)}</span><StatusPill status={job.status}/>{to&&<ChevronRight size={17}/>}</div></>;return to?<NavLink className="job-row clickable-row" to={to}>{content}</NavLink>:<div className="job-row">{content}</div>}
function EmptyPanel({title,copy}:{title:string;copy:string}){return <div className="panel empty"><EmptyState title={title} copy={copy}/></div>} function EmptyState({title,copy}:{title:string;copy:string}){return <div className="empty-state"><div className="empty-icon">N</div><h3>{title}</h3><p>{copy}</p></div>} function ModulePage({name}:{name:string}){return <section className="page"><PageHeading eyebrow="NORTHBORN MODULE" title={name} subtitle="This module is next in the build queue."/><EmptyPanel title={`${name} foundation ready`} copy="The navigation and data foundation are in place. Operational workflows are being built in priority order."/></section>}
function formatDate(value:string|null){if(!value)return'Not scheduled';return new Intl.DateTimeFormat('en-CA',{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(value))} function readError(error:unknown){return error instanceof Error?error.message:String((error as {message?:string})?.message||error||'Something went wrong.')}
